html:
{% set dob = frappe.db.get_value("Patient", doc.patient, "dob") %}
{% set years = 0 %}
{% set months = 0 %}
{% set days = 0 %}
{% if dob %}
    {% set now  = frappe.utils.nowdate() %}
    {% set diff = frappe.utils.date_diff(now, dob) %}
    {% set years = diff//365 %}
    {% set months = (diff - (years * 365))//30 %}
    {% set days = ( (diff - (years * 365)) - (months * 30) ) %}
{% endif %}
{% set age_display = "" %}
{% if years > 0 %}
    {% set age_display = years|str + 'Y' %}
{% else %}
    {% set age_display = months|str + 'M ' + days|str + 'D'  %}
{% endif %}
<div style="font-family: arial, sans-serif;">
    <b><div style="text-align: center; margin-bottom: -2px; font-size:8px;">{{doc.patient_name|upper}}<br>
    {{doc.patient}}, {{age_display}} / {{doc.patient_gender[:1]}}</div>
    <div style="text-align:center;"><img class="barcode" style="width: 350px; height: 50px;" src="data:image/png;base64,{{ generate_barcodes(doc.name) }}"></div>
    <div  style="text-align:center; font-size:8px; margin-top: -8px;">{{doc.name}}</div>
    <div style="text-align: center; font-size:8px;">{{doc.specimen_type|upper}}</div></b>
</div>

css:
/* ===============================
   إعدادات عامة
=============================== */
@page {
  size: A4;
  margin-top: 15mm;
  margin-bottom: 15mm;
  margin-left: 15mm;
  margin-right: 15mm;
}

body {
  font-family: "Cairo", "Tajawal", "Almarai", sans-serif;
  direction: rtl;
  text-align: right;
  font-size: 12px;
  color: #000;
}

/* ===============================
   العناوين
=============================== */
h1, h2, h3, h4 {
  text-align: center;
  font-weight: bold;
  margin-bottom: 10px;
}

.section-head {
  text-align: right;
  font-weight: bold;
  font-size: 14px;
  border-bottom: 1px solid #ccc;
  margin: 15px 0 8px;
  padding-bottom: 4px;
}

/* ===============================
   الحقول والتسميات
=============================== */
.label {
  font-weight: 600;
  text-align: right;
  float: right;
  width: 35%;
  padding-left: 10px;
}

.value {
  text-align: right;
  float: right;
  width: 65%;
}

/* محاذاة التسميات لليمين */
.align-labels-right .label {
  text-align: right;
}

/* ===============================
   الجداول
=============================== */
table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 10px;
}

th, td {
  border: 1px solid #444;
  padding: 6px 8px;
  text-align: right;
  vertical-align: middle;
}

th {
  background-color: #f2f2f2;
  font-weight: bold;
}

/* ===============================
   إظهار فواصل بعد الأقسام
=============================== */
.section {
  margin-bottom: 20px;
  padding-bottom: 10px;
  border-bottom: 1px dashed #bbb;
}

/* ===============================
   الأرقام والقيم
=============================== */
.number,
.currency {
  direction: ltr;
  text-align: right;
}

/* عرض القيم السالبة كموجبة (Visual فقط) */
.absolute-value {
  unicode-bidi: bidi-override;
}

/* ===============================
   رقم الصفحة (إخفاء)
=============================== */
.page-number,
.pagenum,
.footer {
  display: none !important;
}

/* ===============================
   تحسين الطباعة
=============================== */
.no-print {
  display: none !important;
}

.clearfix::after {
  content: "";
  display: block;
  clear: both;
}

/* ========================== CSS ========================== */
@page { size: A4; margin: 15mm 15mm; }

.print-format {
    font-family: "Sultan Regular","Tahoma",Arial,sans-serif;
    direction: rtl;
    text-align: right;
    font-size: 12px;
    line-height: 1.5;
    color: #000;
    background: #fff;
}

/* رأس التقرير */
.report-header {
    text-align: center;
    margin-bottom: 15px;
    padding: 10px 0;
    border-bottom: 2px solid #333;
    background-color: #f5f5f5;
    border-radius: 8px;
}
.report-header .title {
    font-family: "Sultan Bold","Tahoma";
    font-size: 22px;
    font-weight: bold;
    color: #000;
    margin-bottom: 4px;
}
.report-header .sub-title {
    font-size: 14px;
    color: #555;
}

/* العناوين الفرعية */
.print-format h2, .print-format h3 {
    font-family: "Sultan Bold","Tahoma";
    font-weight: bold;
    color: #000;
    page-break-after: avoid;
}
.print-format h2 {
    font-size: 16px;
    margin: 18px 0 10px;
    padding: 8px 10px;
    background: #eef2f5;
    border-right: 4px solid #2c3e50;
    border-radius: 4px;
}
.print-format h3 {
    font-size: 13px;
    margin: 12px 0 6px;
    padding-right: 6px;
    border-right: 3px solid #3498db;
}

/* الأقسام */
.section-container { 
    page-break-inside: avoid; 
    margin-bottom: 12px;
}

/* صناديق المعلومات */
.info-box {
    margin-bottom: 12px;
    padding: 10px;
    background: #fff;
    border: 1px solid #ccc;
    border-radius: 6px;
}
.info-box span {
    display: inline-block;
    min-width: 130px;
    font-weight: bold;
    color: #222;
}

/* الجداول */
.print-format table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 12px;
    background-color: #fff;
    table-layout: fixed;
}
.print-format th {
    background: #f0f0f0;
    border: 1px solid #999;
    padding: 6px 4px;
    text-align: center;
    font-size: 12px;
    font-weight: bold;
    color: #000;
    vertical-align: middle;
}
.print-format td {
    border: 1px solid #bbb;
    padding: 5px 6px;
    vertical-align: top;
    word-wrap: break-word;
    overflow-wrap: break-word;
    font-size: 11.5px;
}
thead { display: table-header-group; }
tr { page-break-inside: avoid; }

/* Child Tables Headers */
.print-format table tbody tr:nth-child(odd) {
    background-color: #fcfcfc;
}
.print-format table tbody tr:nth-child(even) {
    background-color: #f9f9f9;
}

/* التوصيات والملاحظات */
.print-format .recommendations {
    margin-top: 8px;
    padding: 10px;
    background: #fbfbfb;
    border: 1px solid #ddd;
    border-right: 3px solid #27ae60;
    border-radius: 5px;
}
.print-format .recommendations ol, 
.print-format .recommendations ul,
.print-format ol,
.print-format ul {
    padding-right: 20px !important;
    padding-left: 0 !important;
    margin-right: 0;
    text-align: right;
    direction: rtl;
}
.print-format .recommendations li,
.print-format li {
    margin-bottom: 4px;
    line-height: 1.6;
}

/* تحسين عرض الحقول الكبيرة */
.print-format td span, .print-format td div {
    display: block;
    word-wrap: break-word;
}

/* فواصل الأعمدة (Column Break) */
.column-break {
    display: inline-block;
    width: 10px;
}

/* أحجام الخط للحقول الأساسية */
.print-format .info-box, .print-format td, .print-format th {
    font-size: 12px;
}

/* ========================= جداول فيما يخص الوقف ========================= */
.print-format .waqf-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 15px;
    table-layout: fixed;
}
.print-format .waqf-table th {
    background-color: #dce6f1;
    border: 1px solid #999;
    padding: 6px 4px;
    text-align: center;
}
.print-format .waqf-table td {
    border: 1px solid #bbb;
    padding: 5px 6px;
    text-align: center;
}

/* ========================= جداول فيما يخص القرآنية ========================= */
.print-format .quranic-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 15px;
    table-layout: fixed;
}
.print-format .quranic-table th {
    background-color: #f7e6d7;
    border: 1px solid #999;
    padding: 6px 4px;
    text-align: center;
}
.print-format .quranic-table td {
    border: 1px solid #bbb;
    padding: 5px 6px;
    text-align: center;
}

/* صفوف متناوبة للجداول الجديدة */
.print-format .waqf-table tbody tr:nth-child(odd),
.print-format .quranic-table tbody tr:nth-child(odd) {
    background-color: #fcfcfc;
}
.print-format .waqf-table tbody tr:nth-child(even),
.print-format .quranic-table tbody tr:nth-child(even) {
    background-color: #f9f9f9;
}

.print-format {
    direction: rtl;
    font-family: 'Tajawal', 'Cairo', system-ui, sans-serif;
    background-color: #ffffff;
}

.custom-survey-wrapper {
    color: #1e293b;
    font-size: 14px;
}

.survey-header-main {
    background: linear-gradient(135deg, #0f172a, #334155) !important;
    color: #ffffff !important;
    padding: 25px;
    text-align: center;
    border-radius: 12px;
    margin-bottom: 30px;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}

.company-title { font-size: 32px; font-weight: 900; margin-bottom: 8px; color: #f8fafc; }
.form-subtitle { font-size: 18px; font-weight: 500; color: #94a3b8; }

.main-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; align-items: stretch; margin-bottom: 25px; }
.grid-2-cols { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-bottom: 15px;}
.grid-3-cols { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 20px; }

.survey-section {
    background: #ffffff;
    border-radius: 16px;
    margin-bottom: 25px;
    border: 1px solid #e2e8f0;
    display: flex;
    flex-direction: column;
    break-inside: avoid; /* لتجنب قطع القسم بين صفحتين أثناء الطباعة */
}

.section-title {
    background-color: #eff6ff !important; color: #2563eb !important; padding: 12px 20px; font-size: 16px;
    font-weight: 700; display: inline-block; border-radius: 0 0 0 12px;
    border-bottom: 2px solid #bfdbfe; border-left: 2px solid #bfdbfe; align-self: flex-start;
    -webkit-print-color-adjust: exact;
}

.section-title.right-badge {
    border-radius: 0 12px 0 0; border-left: none; border-right: 2px solid #bfdbfe; align-self: flex-end;
}

.section-content { padding: 25px; flex-grow: 1; display: flex; flex-direction: column; }

.form-row-custom { display: flex; align-items: center; margin-bottom: 15px; }
.form-row-custom label { flex: 1; font-weight: 600; color: #475569; margin: 0; font-size: 14px; }

/* بديل الـ Inputs في الطباعة ليظهر كحقل معبأ */
.print-val {
    flex: 2; 
    background: #f8fafc !important; 
    border: 1px solid #cbd5e1; 
    border-radius: 8px;
    padding: 10px 15px; 
    color: #0f172a; 
    width: 100%; 
    box-sizing: border-box;
    min-height: 42px;
    -webkit-print-color-adjust: exact;
}
.textarea-val { min-height: 80px; white-space: pre-wrap; }

.checkbox-group { display: flex; flex-direction: column; gap: 12px; background: #f8fafc !important; padding: 15px; border-radius: 8px; border: 1px solid #e2e8f0; -webkit-print-color-adjust: exact;}
.checkbox-group.horizontal { flex-direction: row; gap: 25px; background: transparent !important; padding: 0; border: none; }
.checkbox-custom { display: flex; align-items: center; font-weight: 500; color: #334155; }
.checkbox-custom input[type="radio"] {
    -webkit-appearance: none; appearance: none; background-color: #fff !important; margin-left: 10px;
    width: 18px; height: 18px; border: 2px solid #cbd5e1; border-radius: 50%;
    display: inline-flex; align-items: center; justify-content: center; flex-shrink: 0;
    -webkit-print-color-adjust: exact;
}
.checkbox-custom input[type="radio"]:checked { border-color: #2563eb; }
.checkbox-custom input[type="radio"]:checked::before {
    content: ""; width: 8px; height: 8px; border-radius: 50%; background-color: #2563eb !important;
    -webkit-print-color-adjust: exact;
}

.section-subtitle { text-align: center; margin-bottom: 20px; color: #64748b; font-weight: 700; font-size: 15px; position: relative; }
.section-subtitle::after { content: ""; display: block; width: 50px; height: 3px; background: #cbd5e1 !important; margin: 8px auto 0; border-radius: 2px; -webkit-print-color-adjust: exact;}
hr.modern-divider { border: none; height: 1px; background: linear-gradient(to right, transparent, #cbd5e1, transparent) !important; margin: 25px 0; -webkit-print-color-adjust: exact;}

/* تنسيق الجداول في الطباعة */
.child-table-placeholder { margin: 10px 0 20px 0; }
.table-custom { width: 100%; border-collapse: collapse; font-size: 13px; background: #fff; }
.table-custom th, .table-custom td { border: 1px solid #cbd5e1; padding: 8px 12px; text-align: right; }
.table-custom th { background-color: #f1f5f9 !important; color: #475569; font-weight: 700; -webkit-print-color-adjust: exact; }
.empty-table { background: #f8fafc !important; border: 1px dashed #cbd5e1; padding: 15px; text-align: center; color: #94a3b8; border-radius: 8px; -webkit-print-color-adjust: exact; }

html:
{%- if letter_head and not no_letterhead -%}
    {{ letter_head }}
{%- endif -%}

<style>
    .tech-block {
        direction: rtl;
        font-family: 'Segoe UI', Tahoma, Arial, sans-serif;
        line-height: 1.8;
        color: #000;
        position: relative;
    }

    /* تنسيق الإشاري والتاريخ ليكون في أعلى اليسار فوق الخط */
    .reference-section {
        text-align: left;
        font-size: 13px;
        margin-bottom: 5px; /* مسافة بسيطة قبل الخط العلوي للعنوان */
        padding-left: 5px;
    }

    .document-title {
        text-align: center;
        font-size: 24px;
        font-weight: bold;
        color: #000;
        border-top: 2px solid #000;
        border-bottom: 2px solid #000;
        padding: 15px 0;
        margin-bottom: 30px;
    }

    .client-details {
        border: 1px solid #e0e0e0;
        border-right: 4px solid #000;
        padding: 15px 20px;
        margin-bottom: 35px;
        background: #f9f9f9;
    }

    .client-details p { margin: 8px 0; font-size: 15px; }
    .client-details strong { display: inline-block; min-width: 160px; }

    .quotation-section { margin-bottom: 40px; }

    .tech-content-body {
        position: relative;
        overflow-x: hidden;
        padding-left: 20px;
    }

    /* تنسيق العناوين السوداء */
    .tech-content-body h1, .tech-content-body h2, .tech-content-body h3,
    .tech-content-body h4, .tech-content-body h5, .tech-content-body h6 {
        position: relative !important;
        display: inline-block !important;
        background: #000 !important;
        color: #fff !important;
        padding: 8px 18px !important;
        margin-top: 25px !important;
        margin-bottom: 15px !important;
        font-size: 18px !important;
        border-radius: 2px !important;
        z-index: 5 !important;
    }

    /* الخطوط المائلة الجانبية */
    .tech-content-body h1::before, .tech-content-body h2::before, .tech-content-body h3::before,
    .tech-content-body h4::before, .tech-content-body h5::before, .tech-content-body h6::before {
        content: "";
        position: absolute !important;
        top: 0;
        right: 100%;
        width: 350px; 
        height: 100%;
        background-image: repeating-linear-gradient(45deg, #000, #000 2px, transparent 2px, transparent 6px) !important;
        z-index: -1;
    }

    .tech-content-body p { margin: 10px 0; text-align: justify; }
    .tech-content-body ul { padding-right: 25px; list-style-type: square; }
</style>

<div class="tech-block">

    <!-- قسم الإشاري والتاريخ يظهر هنا أولاً (فوق الخط) -->
    <div class="reference-section">
        <p style="margin: 0;"><strong>الإشاري:</strong> {{ doc.name }}</p>
        <p style="margin: 0;"><strong>التاريخ:</strong> {{ doc.get_formatted("transaction_date") }}</p>
    </div>

    <div class="document-title">
        العرض الفني والمالي
    </div>

    <div class="client-details">
        <p><strong>اسم العميل:</strong> {{ doc.customer_name or "" }}</p>
        <p><strong>عنوان المشروع:</strong> {{ doc.project_name or "" }}</p>
    </div>

    {% if doc.items and doc.items|length > 0 %}
        {% for row in doc.items %}
            <div class="quotation-section">
                <div class="tech-content-body">
                    {% set content = row.technical_content or doc.technical_content or "" %}

                    {# استبدال المتغيرات #}
                    {% set content = content.replace("{{price_from}}", (row.price_from or 0)|string) %}
                    {% set content = content.replace("{{price_to}}", (row.price_to or 0)|string) %}
                    {% set content = content.replace("{{total_from}}", (doc.total_from or 0)|string) %}
                    {% set content = content.replace("{{total_to}}", (doc.total_to or 0)|string) %}

                    {{ content | safe }}
                </div>
            </div>
        {% endfor %}
    {% else %}
        <div class="tech-content-body">
            {% set content = doc.technical_content or "" %}
            {{ content | safe }}
        </div>
    {% endif %}

</div>

{%- if footer and not no_letterhead -%}
    {{ footer }}
{%- endif -%}

{%- if letter_head and not no_letterhead -%}
    {{ letter_head }}
{%- endif -%}

