    <!-- بيانات العميل -->
    <div class="client-details">
        <p>
            <strong>اسم العميل:</strong>
            {{ doc.customer_name or "" }}
        </p>

        <p>
            <strong>عنوان العرض الفني:</strong>
            {{ doc.project_name or "" }}
        </p>
    </div>

    <!-- محتوى العرض الفني -->
    <div class="quotation-section">
        <div class="tech-content-body">

            {% set content = doc.ardtxt or "" %}

            {# استبدال المتغيرات الرئيسية #}
            {% set content = content.replace("{{customer_name}}", (doc.customer_name or "")) %}
            {% set content = content.replace("{{project_name}}", (doc.project_name or "")) %}
            {% set content = content.replace("{{total_from}}", (doc.total_from or 0)|string) %}
            {% set content = content.replace("{{total_to}}", (doc.total_to or 0)|string) %}

            {# في حالة وجود Child Table يتم استخدام أول صف كمرجع للمتغيرات #}
            {% if doc.ard and doc.ard|length > 0 %}
                {% set first_row = doc.ard[0] %}

                {% set content = content.replace("{{land_area}}", (first_row.land_area or 0)|string) %}
                {% set content = content.replace("{{price_from}}", (first_row.price_from or 0)|string) %}
                {% set content = content.replace("{{price_to}}", (first_row.price_to or 0)|string) %}
            {% endif %}

            {{ content | safe }}

        </div>
    </div>

</div>

{%- if footer and not no_letterhead -%}
    {{ footer }}
{%- endif -%}

