/* ============================================================
   كشف درجات الامتحان - تصميم رسمي أبيض/أسود مخصص للطباعة A4
   ============================================================ */

/* ---------- خط Cairo ---------- */
@font-face {
    font-family: "Cairo";
    src: url("/assets/frappe/fonts/cairo/Cairo-Regular.ttf") format("truetype");
    font-weight: 400;
    font-style: normal;
}
@font-face {
    font-family: "Cairo";
    src: url("/assets/frappe/fonts/cairo/Cairo-Bold.ttf") format("truetype");
    font-weight: 700;
    font-style: normal;
}

/* ==========================================
   PRINT COMMANDS
   ========================================== */
@page {
    size: A4 portrait;
    margin: 0mm !important;
}

html, body {
    margin: 0 !important;
    padding: 0 !important;
    width: 210mm !important;
}

.score-sheet {
    box-sizing: border-box;
    width: 210mm !important;
    min-height: 297mm;
    max-width: 210mm;
    margin: 0 auto !important;
}

@media print {
    table, .ta-field, .sec-title {
        page-break-inside: auto !important;
        break-inside: auto !important;
    }
    tr {
        page-break-inside: avoid !important;
        break-inside: avoid !important;
    }
}

.score-sheet {
    direction: rtl;
    font-family: "Cairo", "Tahoma", "Segoe UI", sans-serif;
    color: #000000;
    background: #ffffff;
    font-size: 8pt;
    line-height: 1.15;
    width: 100%;
    max-width: 100%;
    margin: 0;
    padding: 0;
}

.score-sheet * {
    color: #000000;
    box-shadow: none !important;
    background-image: none !important;
    text-shadow: none !important;
}

/* ---------- الترويسة الرسمية (الشعار / الجهة / التاريخ) ---------- */
.hdr-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 3pt;
}
.hdr-table td {
    border: none;
    padding: 1pt 3pt;
    vertical-align: middle;
}
.hdr-right-cell img {
    display: block;
    height: 40pt;
    width: auto;
    max-width: 100%;
    object-fit: contain;
    margin-right: 0;
    margin-left: auto; /* لأن الخلية RTL ومحاذاة يمين */
}
.hdr-right-cell {
    max-height: 32pt;
    max-width: 100%;
}
.hdr-center-cell {
    width: 64%;
    text-align: center;
}
.hdr-left-cell {
    width: 18%;
    text-align: left;
    vertical-align: top;
}
.c-country {
    font-size: 9pt;
    font-weight: 700;
}
.c-org {
    font-size: 8pt;
    font-weight: 700;
}
.c-dept {
    font-size: 7.5pt;
    font-weight: 400;
}
.single-line-date {
    font-size: 7pt;
    white-space: nowrap;
}
.c-orgs {
    font-weight: 400;
}

/* ---------- الترويسة ---------- */
.sheet-header {
    text-align: center;
    border-bottom: 1pt solid #000000;
    padding-bottom: 3pt;
    margin-bottom: 5pt;
}
.sheet-header h1 {
    margin: 0;
    font-size: 10.5pt;
    font-weight: 700;
}
.header-subtitle {
    margin-top: 2pt;
    font-size: 7.5pt;
    font-weight: 400;
}

/* ---------- الأقسام ---------- */
.section {
    margin-bottom: 5pt;
    page-break-inside: avoid;
}
.section-title {
    font-size: 8.5pt;
    font-weight: 700;
    background: #efefef;
    border: 1pt solid #000000;
    padding: 2pt 5pt;
    margin-bottom: 3pt;
}

/* ---------- جدول بيانات الواعظ ---------- */
.info-table,
.final-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 2pt;
    table-layout: fixed;
}
.info-table td,
.final-table td {
    border: 1pt solid #000000;
    padding: 2pt 4pt;
    vertical-align: middle;
    font-size: 7.5pt;
    word-wrap: break-word;
}
.info-label {
    background: #efefef;
    font-weight: 700;
    width: 17%;
    white-space: nowrap;
}
.info-value {
    width: 33%;
    font-weight: 400;
}
.final-pass-status {
    font-weight: 700;
    text-align: center;
}

/* ---------- جداول الدرجات (Pivot) ---------- */
.pivot-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    margin-bottom: 3pt;
}
.pivot-table th,
.pivot-table td {
    border: 1pt solid #000000;
    padding: 2pt 3pt;
    text-align: center;
    font-size: 7.5pt;
    overflow-wrap: break-word;
}
.pivot-table thead th {
    background: #efefef;
    font-weight: 700;
}
/* تكرار رأس الجدول تلقائيا في بداية كل صفحة عند الطباعة */
.pivot-table thead {
    display: table-header-group;
}
.pivot-table tfoot {
    display: table-footer-group;
}
.pivot-table tbody tr {
    page-break-inside: avoid;
}
.pivot-table .aspect-col {
    text-align: right;
    font-weight: 700;
    width: 22%;
    white-space: normal;
}
.pivot-table .total-col {
    font-weight: 700;
    background: #f5f5f5;
}
.pivot-table tfoot td {
    background: #efefef;
    font-weight: 700;
}
.pivot-table tfoot .total-label {
    text-align: right;
}

/* تصغير تلقائي للخط والحشو عند زيادة عدد الأسئلة/الأعمدة */
.pivot-table.compact th,
.pivot-table.compact td {
    font-size: 7pt;
    padding: 1.5pt 2pt;
}
.pivot-table.ultra-compact th,
.pivot-table.ultra-compact td {
    font-size: 6.5pt;
    padding: 1pt 1.5pt;
}

/* ---------- ملخص كل مرحلة ---------- */
.stage-summary-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    margin-bottom: 2pt;
}
.stage-summary-table td {
    border: 1pt solid #000000;
    padding: 2pt 3pt;
    font-size: 7.5pt;
    text-align: center;
}
.stage-summary-table .stage-label {
    background: #efefef;
    font-weight: 700;
    width: 14%;
}
.stage-summary-table .stage-value {
    width: 19.6%;
    font-weight: 400;
}

/* ---------- التذييل ---------- */
.sheet-footer {
    margin-top: 4pt;
    border-top: 0.75pt solid #000000;
    padding-top: 2pt;
    text-align: center;
}
.footer-note {
    font-size: 7pt;
}

/* ---------- الشاشة (عرض غير الطباعة) ---------- */
@media screen {
    .score-sheet {
        max-width: 210mm;
        margin: 0 auto;
        padding: 6mm;
        border: 1px solid #000000;
    }
}

/* ---------- الطباعة ---------- */
