}
.pivot-table .total-col {
    font-weight: 700;
    background: #f5f5f5;
}
.pivot-table tfoot td {
    background: #efefef;
    font-weight: 700;
}
.pivot-table tfoot .total-label {
    text-align: right;
}

/* تصغير تلقائي للخط والحشو عند زيادة عدد الأسئلة/الأعمدة */
.pivot-table.compact th,
.pivot-table.compact td {
    font-size: 8.5pt;
    padding: 2pt 3pt;
}
.pivot-table.ultra-compact th,
.pivot-table.ultra-compact td {
    font-size: 7.5pt;
    padding: 1.5pt 2pt;
}

/* ---------- ملخص كل مرحلة ---------- */
.stage-summary-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    margin-bottom: 2pt;
}
.stage-summary-table td {
    border: 1pt solid #000000;
    padding: 2.5pt 4pt;
    font-size: 8.5pt;
    text-align: center;
}
.stage-summary-table .stage-label {
    background: #efefef;
    font-weight: 700;
    width: 14%;
}
.stage-summary-table .stage-value {
    width: 19.6%;
    font-weight: 400;
}

/* ---------- التذييل ---------- */
.sheet-footer {
    margin-top: 6pt;
    border-top: 0.75pt solid #000000;
    padding-top: 3pt;
    text-align: center;
}
.footer-note {
    font-size: 7.5pt;
}

/* ---------- الشاشة (عرض غير الطباعة) ---------- */
@media screen {
    .score-sheet {
        max-width: 210mm;
        margin: 0 auto;
        padding: 8mm;
        border: 1px solid #000000;
    }
}

/* ---------- الطباعة ---------- */
@media print {
    .score-sheet {
        padding: 8mm;
        border: none;
    }
    .section {
        page-break-inside: avoid;
    }
}
/* ---------- قسم التوقيعات ---------- */
.signatures-section {
    margin-top: 12pt;
}
.signatures-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
}
.signatures-table .sig-cell {
    border: 1pt solid #000000;
    padding: 6pt 5pt 12pt;
    width: 33.33%;
    text-align: center;
    vertical-align: top;
}
.sig-role {
    font-weight: 700;
    font-size: 9pt;
    margin-bottom: 4pt;
}
.sig-name {
    font-size: 9pt;
    font-weight: 400;
    margin-bottom: 12pt;
    min-height: 11pt;
}
.sig-line {
    font-size: 8.5pt;
    font-weight: 400;
}

/* ==========================================================================
   إدارة الشؤون الثقافية والدعوية - الهيئة العامة للأوقاف والشؤون الإسلامية
   تنسيق إجازة الوعظ العام - إزالة إطار الدائرة والنص البديل كلياً عند وجود الشعار
   ========================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Amiri:ital,wght@0,400;0,700;1,400;1,700&family=Reem+Kufi:wght@400;500;600;700&family=Tajawal:wght@400;500;700;800&display=swap');

:root {
    --primary-green: #0B3C26;
    --primary-green-dark: #062215;
    --accent-gold: #C5A059;
    --accent-gold-light: #E8D3A7;
    --bg-white: #FFFFFF;
    --text-dark: #122019;
    --text-muted: #485A52;
}

body {
    background-color: #FFFFFF !important;
    font-family: 'Tajawal', 'Amiri', 'Traditional Arabic', serif;
    margin: 0;
    padding: 0;
    color: #122019;
    direction: rtl;
    -webkit-font-smoothing: antialiased;
}

/* الحاوية الرئيسية A4 بمسافة أمان تضمن ظهور الإطار كاملاً في الطباعة والـ PDF */
.certificate-wrapper {
    font-family: 'Tajawal', 'Amiri', 'Traditional Arabic', serif !important;
    direction: rtl !important;
    text-align: right !important;
    padding: 4mm !important;
    margin: 0 auto !important;
    background-color: #FFFFFF !important;
    background-image: none !important;
    color: #122019 !important;
    width: 210mm !important;
    height: 297mm !important;
    box-sizing: border-box !important;
    position: relative !important;
    overflow: hidden !important;
}

/* الإطار الخارجي الأخضر الملكي الكامل الظاهر في الطباعة */
.border-outer {
    border: 5px solid #0B3C26 !important;
    height: 100% !important;
    padding: 3px !important;
    box-sizing: border-box !important;
    background-color: #FFFFFF !important;
}

/* الإطار الداخلي الذهبي المحيط بكافة الصفحة */
.certificate-inner {
    border: 2px solid #C5A059 !important;
    height: 100% !important;
    padding: 14px 18px 4px 18px !important;
    position: relative !important;
    box-sizing: border-box !important;
    background-color: #FFFFFF !important;
    display: flex !important;
    flex-direction: column !important;
    justify-content: space-between !important;
}

/* الترويسة والشعارات */
.header-table {
    width: 100% !important;
    margin-bottom: 4px !important;
    text-align: center !important;
    border-collapse: collapse !important;
}

.header-table td { vertical-align: middle !important; }
.logo-cell { width: 22% !important; }
.title-cell { width: 56% !important; padding: 0 5px !important; }

/* حاوية الشعار شفافة ونظيفة تماماً */
.logo-placeholder {
    width: 90px !important;
    height: 90px !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    margin: 0 auto !important;
    background: transparent !important;
    border: none !important;
    position: relative !important;
}

/* صورة الشعار تظهر بروّعة وحجم متناسق دون إطارات دائرية أو نصوص تداخل */
.clean-logo-img {
    max-width: 100% !important;
    max-height: 90px !important;
    width: auto !important;
    height: auto !important;
    object-fit: contain !important;
    display: block !important;
    border: none !important;
    background: transparent !important;
    box-shadow: none !important;
    border-radius: 0 !important;
    margin: 0 auto !important;
}

/* النص البديل يظهر فقط إذا لم يتم إضافة صورة شعار إطلاقاً */
.logo-inner {
    width: 82px !important;
    height: 82px !important;
    border-radius: 50% !important;
    border: 2px solid #C5A059 !important;
    background: #FFFFFF !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    font-size: 11px !important;
    font-weight: bold !important;
    color: #0B3C26 !important;
    text-align: center !important;
    padding: 3px !important;
    line-height: 1.3 !important;
    font-family: 'Tajawal', sans-serif !important;
    box-sizing: border-box !important;
}

.title-cell h3 {
    margin: 2px 0 !important;
    font-size: 16.5px !important;
    font-weight: bold !important;
    color: #0B3C26 !important;
    font-family: 'Tajawal', sans-serif !important;
}

.title-cell h1 {
    margin: 4px 0 2px 0 !important;
    font-size: 28px !important;
    font-weight: bold !important;
    color: #062215 !important;
    font-family: 'Reem Kufi', 'Amiri', 'Traditional Arabic', serif !important;
}

.title-divider {
    text-align: center !important;
    margin: 2px 0 !important;
}

.gold-star {
    color: #C5A059 !important;
    font-size: 14px !important;
}

.decorative-separator {
    text-align: center !important;
    margin: 4px auto 4px auto !important;
    width: 85% !important;
    border-bottom: 1px solid #C5A059 !important;
    position: relative !important;
    height: 8px !important;
}

.pattern-emblem {
    color: #C5A059 !important;
    font-size: 16px !important;
    background: #FFFFFF !important;
    padding: 0 10px !important;
    position: relative !important;
    top: 0px !important;
    display: inline-block !important;
}

/* محتوى الإجازة والبيانات */
.certificate-content {
    display: flex !important;
    flex-direction: column !important;
    justify-content: flex-start !important;
    margin-top: 4px !important;
}

.data-row {
    display: flex !important;
    align-items: center !important;
    margin-bottom: 6px !important;
    font-size: 17.5px !important;
    font-weight: bold !important;
    background: #FFFFFF !important;
    padding: 6px 10px !important;
    border-radius: 6px !important;
    border: 1px solid #E8D3A7 !important;
    border-right: 5px solid #C5A059 !important;
}

.data-row.grid-2-col {
    display: table !important;
    width: 100% !important;
    table-layout: fixed !important;
    background: transparent !important;
    padding: 0 !important;
    border: none !important;
    margin-bottom: 6px !important;
}

.field-group-cell {
    display: table-cell !important;
    width: 50% !important;
    vertical-align: middle !important;
}

.field-group-cell:first-child { padding-left: 5px !important; }
.field-group-cell:last-child { padding-right: 5px !important; }

.field-group {
    display: flex !important;
    align-items: center !important;
    background: #FFFFFF !important;
    padding: 6px 10px !important;
    border-radius: 6px !important;
    border: 1px solid #E8D3A7 !important;
    border-right: 5px solid #C5A059 !important;
}

.row-label {
    white-space: nowrap !important;
    color: #0B3C26 !important;
    font-family: 'Tajawal', sans-serif !important;
    font-weight: bold !important;
    font-size: 16.5px !important;
    margin-left: 6px !important;
}

.dotted-field {
    border-bottom: 2px dashed #C5A059 !important;
    text-align: center !important;
    padding: 2px 8px !important;
    color: #062215 !important;
    margin: 0 4px !important;
    font-family: 'Amiri', 'Traditional Arabic', serif !important;
    font-size: 20px !important;
    font-weight: bold !important;
    background-color: rgba(11, 60, 38, 0.03) !important;
    border-radius: 3px 3px 0 0 !important;
    display: inline-block !important;
}

.flex-fill { flex-grow: 1 !important; width: 100% !important; }
.fixed-medium { min-width: 125px !important; flex-grow: 1 !important; }
.fixed-small { min-width: 70px !important; flex-grow: 1 !important; }

/* زيادة طول المحتوى النصي الأوسط رأسياً */
.text-body-container {
    background: #FFFFFF !important;
    border: 1px solid #C5A059 !important;
    border-radius: 8px !important;
    padding: 26px 24px !important;
    margin-top: 8px !important;
    margin-bottom: 8px !important;
}

.paragraph-text {
    text-align: justify !important;
    text-align-last: auto !important;
    text-justify: inter-word !important;
    margin-top: 11px !important;
    margin-bottom: 11px !important;
    font-size: 21.5px !important;
    line-height: 2.3 !important;
    font-weight: bold !important;
    font-family: 'Amiri', 'Traditional Arabic', serif !important;
    color: #122019 !important;
}

.paragraph-text:first-child { margin-top: 0 !important; }

.paragraph-text.center-text {
    text-align: center !important;
    text-align-last: center !important;
    font-size: 21.5px !important;
    color: #0B3C26 !important;
    margin-top: 16px !important;
    padding-top: 12px !important;
    border-top: 1px dashed #C5A059 !important;
}

/* جدول التوقيعات */
.signatures-table {
    width: 100% !important;
    margin-top: 20px !important;
    margin-bottom: 4px !important;
    text-align: center !important;
    border-collapse: collapse !important;
}

.signatures-table td {
    width: 38% !important;
    vertical-align: top !important;
    padding: 0 5px !important;
}

.signatures-table td.stamp-cell {
    width: 24% !important;
    vertical-align: middle !important;
}

.sig-box {
    background: #FFFFFF !important;
    border: 1px solid #E8D3A7 !important;
    border-top: 4px solid #C5A059 !important;
    padding: 14px 10px 32px 10px !important;
    min-height: 130px !important;
    border-radius: 0 0 6px 6px !important;
    position: relative !important;
    display: flex !important;
    flex-direction: column !important;
    justify-content: space-between !important;
    box-sizing: border-box !important;
}

.sig-name {
    font-weight: bold !important;
    font-size: 18.5px !important;
    margin-bottom: 3px !important;
    color: #0B3C26 !important;
    font-family: 'Tajawal', sans-serif !important;
}

.sig-role {
    font-size: 15.5px !important;
    color: #485A52 !important;
    font-family: 'Tajawal', sans-serif !important;
    margin-bottom: 6px !important;
}

.sig-line {
    font-size: 15.5px !important;
    font-weight: bold !important;
    color: #0B3C26 !important;
    letter-spacing: 2px !important;
    margin-top: 10px !important;
    padding-top: 4px !important;
    direction: rtl !important;
    font-family: 'Tajawal', sans-serif !important;
}

.official-stamp-placeholder {
    width: 85px !important;
    height: 85px !important;
    margin: 0 auto !important;
    border: 2px dashed #C5A059 !important;
    border-radius: 50% !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
}

.stamp-circle {
    border: 1px solid #C5A059 !important;
    border-radius: 50% !important;
    width: 72px !important;
    height: 72px !important;
    background: #FFFFFF !important;
}

.certificate-footer {
    margin-top: auto !important;
    padding-top: 6px !important;
    padding-bottom: 2px !important;
    text-align: center !important;
    width: 100% !important;
}

.footer-badge {
    display: inline-block !important;
    background-color: #0B3C26 !important;
    color: #FFFFFF !important;
    font-size: 13px !important;
    font-weight: bold !important;
    padding: 5px 24px !important;
    border-radius: 20px !important;
    border: 1px solid #C5A059 !important;
    font-family: 'Tajawal', sans-serif !important;
}

@media print {
    @page {
        size: A4 portrait;
        margin: 0mm;
    }
    html, body {
        margin: 0;
        padding: 0;
        width: 210mm;
        height: 297mm;
        background: #FFFFFF !important;
        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
    }
    .certificate-wrapper {
        padding: 4mm !important;
        margin: 0 !important;
        width: 210mm !important;
        height: 297mm !important;
        box-shadow: none !important;
        background-color: #FFFFFF !important;
        page-break-after: avoid !important;
        page-break-inside: avoid !important;
    }
}
